void Solver::bump_var(int var, double coeff) {
    // Increase activity of the variable by a scaled coefficient
    activity[var] += var_inc * coeff;

    // Prevent floating‑point overflow by rescaling all activities when a limit is exceeded
    const double ACT_LIMIT = 1e100;
    if (activity[var] > ACT_LIMIT) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Keep the VSIDS heap consistent: update if already present, otherwise insert
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
